`include "disciplines.vams"
module positive_clip(n,d,en,ref,y);
input n,d,en,ref; output y;
electrical n,d,en,ref,y;
parameter real lower = 0.6;
real denominator, numerator, result;
analog function real clip;
    input x; real x;
    begin
        if (x < 0.0) clip = 0.0;
        else if (x > 1.0) clip = 1.0;
        else clip = x;
    end
endfunction
real source_scope_witness; analog begin @(initial_step) source_scope_witness = 0;
    denominator = V(d);
    numerator = V(n);
    if ((V(en) > 0.5) && (denominator <= -lower))
        result = clip(numerator / denominator);
    else result = -0.125;
    V(y) <+ result;
end
endmodule

`include "disciplines.vams"
module positive_clip(n,d,en,ref,y);
input n,d,en,ref; output y;
electrical n,d,en,ref,y;
parameter real lower = 0.6;
real denominator, numerator, result;
analog function real clip;
    input x; real x;
    begin
        if (x < 0.0) clip = 0.0;
        else if (x > 1.0) clip = 1.0;
        else clip = x;
    end
endfunction
real source_scope_witness; analog begin @(initial_step) source_scope_witness = 0;
    denominator = V(d);
    numerator = V(n) * V(n);
    if ((V(en) > 0.5) && (denominator >= lower))
        result = clip(numerator / denominator);
    else result = -0.125;
    V(y) <+ result;
end
endmodule
